    --bg-color: #121212;
    --surface-color: #1e1e1e;
    --text-primary: #e0e0e0;
    --text-secondary: #a0a0a0;
    --accent-color: #bb86fc;
    --accent-hover: #9965f4;
    --error-color: #cf6679;
    --border-color: #333333;
    --spacing-unit: 8px;
}

* {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    background-color: var(--bg-color);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
}

/* Accessibility */
.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--accent-color);
    color: #000;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

a {
    color: var(--accent-color);
    text-decoration: none;
    transition: color 0.2s;
}

a:hover {
    color: var(--accent-hover);
}

button {
    cursor: pointer;
    background: none;
    border: none;
    color: inherit;
    font: inherit;
}

/* Header & Nav */
header {
    background-color: rgba(18, 18, 18, 0.95);
    backdrop-filter: blur(8px);
    position: sticky;
    top: 0;
    z-index: 50;
    border-bottom: 1px solid var(--border-color);
}

nav {
    display: flex;
    justify-content: space-between;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto;
    padding: 1rem 2rem;
}

.logo {
    font-size: 1.5rem;
    font-weight: 800;
    letter-spacing: 2px;
}

.nav-links {
    display: flex;
    list-style: none;
    gap: 2rem;
}

.nav-links a {
    color: var(--text-primary);
    font-weight: 500;
}

.header-actions {
    display: flex;
    gap: 1rem;
    align-items: center;
}

/* Hero */
.hero {
    height: 80vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), url('https://images.unsplash.com/photo-1441986300917-64674bd600d8?auto=format&fit=crop&q=80&w=1200') center/cover no-repeat;
    text-align: center;
    padding: 2rem;
}

.hero-h1 {
    font-size: clamp(2.5rem, 8vw, 4.5rem);
    margin-bottom: 1rem;
}

.hero p {
    font-size: 1.25rem;
    color: var(--text-secondary);
    max-width: 600px;
    margin: 0 auto 2rem;
}

.cta-button {
    background-color: var(--accent-color);
    color: #000;
    padding: 1rem 2.5rem;
    border-radius: 4px;
    font-weight: 700;
    display: inline-block;
}

/* Grid Layouts */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 2rem;
    max-width: 1200px;
    margin: 4rem auto;
    padding: 0 2rem;
}

.featured-products h2 {
    text-align: center;
    margin-top: 4rem;
    font-size: 2.5rem;
}

/* Product Card */
.product-card {
    background-color: var(--surface-color);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    overflow: hidden;
    transition: transform 0.3s;
}

.product-card:hover {
    transform: translateY(-4px);
}

.product-image {
    width: 100%;
    aspect-ratio: 1;
    object-fit: cover;
    background-color: #2a2a2a;
}

.product-info {
    padding: 1.5rem;
}

.product-name {
    font-size: 1.1rem;
    margin-bottom: 0.5rem;
}

.product-price {
    font-weight: 700;
    color: var(--accent-color);
}

.add-to-cart {
    width: 100%;
    margin-top: 1rem;
    padding: 0.75rem;
    background: var(--border-color);
    border-radius: 4px;
    transition: background 0.2s;
}

.add-to-cart:hover {
    background: #444;
}

/* Deals */
.deals {
    background-color: var(--surface-color);
    padding: 6rem 2rem;
}

.deals-container {
    max-width: 1200px;
    margin: 0 auto;
}

.deal-card {
    background: linear-gradient(135deg, #2c2c2c, #1a1a1a);
    padding: 3rem;
    border-radius: 12px;
    border-left: 4px solid var(--accent-color);
}

/* Editorial */
.editorial {
    padding: 8rem 2rem;
    max-width: 800px;
    margin: 0 auto;
    text-align: center;
}

.editorial h2 {
    font-size: 3rem;
    margin-bottom: 2rem;
}

.editorial p {
    font-size: 1.4rem;
    color: var(--text-secondary);
    margin-bottom: 2rem;
}

/* Footer */
footer {
    border-top: 1px solid var(--border-color);
    padding: 4rem 2rem 2rem;
    background-color: #0a0a0a;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 2rem;
}

.footer-links {
    list-style: none;
    display: flex;
    gap: 2rem;
}

.footer-links a {
    color: var(--text-secondary);
}

.copyright {
    text-align: center;
    margin-top: 4rem;
    color: var(--text-secondary);
    font-size: 0.9rem;
}

/* Focus states */
:focus-visible {
    outline: 2px solid var(--accent-color);
    outline-offset: 4px;
}

/* Animation */
@keyframes bump {
    0% { transform: scale(1); }
    50% { transform: scale(1.4); }
    100% { transform: scale(1); }
}

#cart-count.bump {
    animation: bump 0.3s ease-out;
    display: inline-block;
}

#cart-count {
    background: var(--accent-color);
    color: #000;
    border-radius: 50%;
    padding: 2px 6px;
    font-size: 0.75rem;
    font-weight: bold;
    margin-left: 4px;
}
