    {
        id: 1,
        name: "Noir Minimalist Watch",
        price: 199.00,
        image: "https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&q=80&w=400"
    },
    {
        id: 2,
        name: "Obsidian Leather Backpack",
        price: 145.00,
        image: "https://images.unsplash.com/photo-1548036654-3d6d443d7912?auto=format&fit=crop&q=80&w=400"
    },
    {
        id: 3,
        name: "Stealth Wireless Headphones",
        price: 299.00,
        image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&q=80&w=400"
    },
    {
        id: 4,
        name: "Carbon Fiber Wallet",
        price: 85.00,
        image: "https://images.unsplash.com/photo-1627123424574-724758594e93?auto=format&fit=crop&q=80&w=400"
    }
];

let cartCount = 0;

function renderProducts() {
    const grid = document.getElementById('product-grid');
    if (!grid) return;

    grid.innerHTML = products.map(product => `
        <article class="product-card">
            <img src="${product.image}" alt="${product.name}" class="product-image">
            <div class="product-info">
                <h3 class="product-name">${product.name}</h3>
                <p class="product-price">$${product.price.toFixed(2)}</p>
                <button 
                    class="add-to-cart" 
                    aria-label="Add ${product.name} to cart"
                    data-id="${product.id}"
                >
                    Add to Cart
                </button>
            </div>
        </article>
    `).join('');

    // Add event listeners
    grid.querySelectorAll('.add-to-cart').forEach(button => {
        button.addEventListener('click', () => {
            const productId = button.getAttribute('data-id');
            const product = products.find(p => p.id == productId);
            addToCart(product.name);
        });
    });
}

function addToCart(productName) {
    cartCount++;
    const countBadge = document.getElementById('cart-count');
    if (countBadge) {
        countBadge.textContent = cartCount;
        countBadge.classList.remove('bump');
        void countBadge.offsetWidth; // Trigger reflow
        countBadge.classList.add('bump');
    }

    // Accessibility: Announce to screen readers
    const announcement = document.getElementById('a11y-announcer');
    if (announcement) {
        announcement.textContent = `${productName} added to cart. Total items: ${cartCount}`;
    }
}

document.addEventListener('DOMContentLoaded', () => {
    // Create live region for announcements
    const announcer = document.createElement('div');
    announcer.id = 'a11y-announcer';
    announcer.setAttribute('aria-live', 'polite');
    announcer.classList.add('sr-only');
    document.body.appendChild(announcer);

    renderProducts();

    // Mock search interaction
    document.getElementById('search-btn')?.addEventListener('click', () => {
        alert('Search feature coming soon!');
    });
});
